// arrow-highlight — a bundled template (spec §11 G-44): a rounded box drawn
// on around a spot and an arrow growing toward it from the side nearer the
// frame's centre, with a label at the arrow's tail.
export const meta = {
  name: "Arrow highlight",
  category: "Screencast",
  description: "A box drawn round a spot, an arrow and a label pointing at it.",
  durationInFrames: 90,
};

export const schema = {
  x:         { type: "number", default: 0.62, min: 0, max: 1, step: 0.01 },
  y:         { type: "number", default: 0.42, min: 0, max: 1, step: 0.01 },
  boxWidth:  { type: "number", default: 0.22, min: 0.02, max: 0.8, step: 0.01 },
  boxHeight: { type: "number", default: 0.14, min: 0.02, max: 0.8, step: 0.01 },
  shape:     { type: "enum",   default: "box+arrow", options: ["box+arrow", "box", "arrow"] },
  label:     { type: "string", default: "Look here" },
  accent:    { type: "color",  default: "#ffd60a" },
};

const clamp = (v, lo, hi) => Math.max(lo, Math.min(Math.max(lo, hi), v));

export function render(frame, props, ctx) {
  const u = Math.min(ctx.width, ctx.height) / 1080;
  const D = ctx.durationInFrames;
  const W = ctx.width;
  const H = ctx.height;
  const inset = 30 * u;
  const x0 = W * 0.05 + inset;
  const y0 = H * 0.05 + inset;
  const x1 = W * 0.95 - inset;
  const y1 = H * 0.95 - inset;
  const showBox = props.shape !== "arrow";
  const showArrow = props.shape !== "box";
  const bw = showBox ? Math.min(x1 - x0, Math.max(0.02, props.boxWidth) * W) : 0;
  const bh = showBox ? Math.min(y1 - y0, Math.max(0.02, props.boxHeight) * H) : 0;
  const cx = clamp(props.x * W, x0 + bw / 2, x1 - bw / 2);
  const cy = clamp(props.y * H, y0 + bh / 2, y1 - bh / 2);
  const stroke = 8 * u;
  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
  const font = { family: "Montserrat", size: 56 * u, weight: 800 };
  const labelSize = props.label ? fitText(props.label, x1 - x0, font, { min: 10 * u, max: font.size }) : 0;
  const labelW = props.label ? measureText(props.label, { family: "Montserrat", size: labelSize, weight: 800 }).width : 0;

  let box = "";
  if (showBox) {
    const r = Math.min(14 * u, bw / 2, bh / 2);
    const bx = cx - bw / 2;
    const by = cy - bh / 2;
    const d = `M ${bx + r} ${by} H ${bx + bw - r} A ${r} ${r} 0 0 1 ${bx + bw} ${by + r} V ${by + bh - r}
      A ${r} ${r} 0 0 1 ${bx + bw - r} ${by + bh} H ${bx + r} A ${r} ${r} 0 0 1 ${bx} ${by + bh - r} V ${by + r}
      A ${r} ${r} 0 0 1 ${bx + r} ${by} Z`;
    const drawn = interpolate(frame, [0, 24], [0, 1], { easing: Easing.inOutCubic, clamp: true });
    const dash = evolvePath(drawn, d);
    box = drawn > 0 ? `<path d="${d}" fill="none" stroke="${props.accent}" stroke-width="${stroke}"
      stroke-linecap="round" stroke-linejoin="round" stroke-dasharray="${dash.strokeDasharray}"
      stroke-dashoffset="${dash.strokeDashoffset}" stroke-opacity="${out}"/>` : "";
  }

  // The tail lies toward the frame's centre (down and left when the spot is the centre).
  let dx = W / 2 - cx;
  let dy = H / 2 - cy;
  const len = Math.hypot(dx, dy);
  if (len < 1) {
    dx = -1;
    dy = 1;
  }
  const norm = Math.hypot(dx, dy);
  dx /= norm;
  dy /= norm;
  // Where the ray from the centre leaves the box (or the spot itself), plus a gap.
  const exit = showBox ? Math.min(bw / 2 / Math.max(1e-6, Math.abs(dx)), bh / 2 / Math.max(1e-6, Math.abs(dy))) : 0;
  const gapped = exit + 22 * u;
  const headX = cx + dx * gapped;
  const headY = cy + dy * gapped;
  const reach = 240 * u;
  const below = dy >= 0;
  const labelRoom = props.label ? labelSize * 1.3 : 0;
  const tailX = clamp(headX + dx * reach, x0 + 10 * u, x1 - 10 * u);
  const tailY = clamp(headY + dy * reach, y0 + (below ? 0 : labelRoom), y1 - (below ? labelRoom : 0));
  const grow = interpolate(frame, [18, 36], [0, 1], { easing: Easing.outBack, clamp: true });
  let arrow = "";
  if (showArrow && grow > 0) {
    const hx = tailX + (headX - tailX) * grow;
    const hy = tailY + (headY - tailY) * grow;
    const angle = Math.atan2(headY - tailY, headX - tailX);
    const head = 34 * u;
    const p1 = `${hx - head * Math.cos(angle - 0.5)},${hy - head * Math.sin(angle - 0.5)}`;
    const p2 = `${hx - head * Math.cos(angle + 0.5)},${hy - head * Math.sin(angle + 0.5)}`;
    const back = 0.8 * head;
    arrow = `<line x1="${tailX}" y1="${tailY}" x2="${hx - back * Math.cos(angle) * 0.5}" y2="${hy - back * Math.sin(angle) * 0.5}"
                   stroke="${props.accent}" stroke-opacity="${out}" stroke-width="${stroke}" stroke-linecap="round"/>
      <polygon points="${hx},${hy} ${p1} ${p2}" fill="${props.accent}" fill-opacity="${out}" stroke="${props.accent}"
               stroke-opacity="${out}" stroke-width="${3 * u}" stroke-linejoin="round"/>`;
  }
  let label = "";
  if (props.label) {
    const t = spring({ frame: frame - (showArrow ? 30 : 20), fps: ctx.fps, damping: 15 });
    let lx;
    let ly;
    if (showArrow) {
      lx = tailX;
      ly = below ? tailY + labelSize * 1.15 : tailY - labelSize * 0.45;
    } else {
      lx = cx;
      ly = cy + bh / 2 + 20 * u + labelSize;
      if (ly > y1) ly = cy - bh / 2 - 26 * u;
    }
    lx = clamp(lx, x0 + labelW / 2, x1 - labelW / 2);
    label = `<text x="${lx}" y="${ly}" text-anchor="middle" font-family="Montserrat" font-weight="800"
          font-size="${labelSize}" fill="#ffffff" stroke="#0b0b10" stroke-width="${9 * u}" stroke-linejoin="round" paint-order="stroke"
          fill-opacity="${Math.max(0, Math.min(1, t)) * out}" stroke-opacity="${Math.max(0, Math.min(1, t)) * out * 0.85}"
          >${escapeXml(props.label)}</text>`;
  }
  return svg(ctx, `${box}${arrow}${label}`);
}
// bar-chart — road map 10 §5k 4: `values` as a comma-separated string, bars
// growing in sequence, labels.
export const meta = {
  name: "Bar chart",
  category: "Data & Time",
  description: "Bars growing one after another, with labels and a title.",
  durationInFrames: 150,
};

export const schema = {
  values: { type: "string", default: "12, 19, 7, 24, 15, 30" },
  labels: { type: "string", default: "Mon, Tue, Wed, Thu, Fri, Sat" },
  title:  { type: "string", default: "Sessions per day" },
  color:  { type: "color",  default: "#2d7ff9" },
};

export function render(frame, props, ctx) {
  const u = Math.min(ctx.width, ctx.height) / 1080;
  const values = props.values.split(",").map((v) => Number(v.trim())).filter((v) => isFinite(v));
  const labels = props.labels.split(",").map((l) => l.trim());
  const top = Math.max(1, ...values);
  const chartLeft = 200 * u;
  const chartRight = ctx.width - 200 * u;
  const base = ctx.height - 200 * u;
  const tall = ctx.height - 460 * u;
  const slot = (chartRight - chartLeft) / Math.max(1, values.length);
  const barWidth = slot * 0.62;
  let bars = "";
  values.forEach((v, i) => {
    const grow = spring({ frame: frame - 10 - i * 8, fps: ctx.fps, damping: 13 });
    const h = (v / top) * tall * grow;
    const x = chartLeft + slot * i + (slot - barWidth) / 2;
    const shown = Math.round(v * Math.min(1, Math.max(0, grow)));
    bars += `<rect x="${x}" y="${base - h}" width="${barWidth}" height="${h}" fill="${props.color}"/>`;
    bars += `<text x="${x + barWidth / 2}" y="${base - h - 16 * u}" text-anchor="middle" font-family="IBM Plex Mono"
                   font-size="${34 * u}" fill="#ffffff" opacity="${Math.min(1, Math.max(0, grow))}">${shown}</text>`;
    bars += `<text x="${x + barWidth / 2}" y="${base + 56 * u}" text-anchor="middle" font-family="Bebas Neue"
                   font-size="${44 * u}" fill="#c8c8d0">${escapeXml(labels[i] || "")}</text>`;
  });
  const titleIn = interpolate(frame, [0, 15], [0, 1], { clamp: true });
  return svg(ctx, `
    <text x="${chartLeft}" y="${150 * u}" font-family="Montserrat" font-weight="900" font-size="${72 * u}"
          fill="#ffffff" opacity="${titleIn}">${escapeXml(props.title)}</text>
    <line x1="${chartLeft}" y1="${base}" x2="${chartRight}" y2="${base}" stroke="#ffffff55" stroke-width="${3 * u}"/>
    ${bars}`, { background: "#15151b" });
}
// callout — road map 10 §5k 6: a circle drawing itself on (a
// stroke-dasharray draw-on) and an arrow, over a transparent background.
export const meta = {
  name: "Callout",
  category: "Screencast",
  description: "A circle drawing itself round a spot, with an arrow and a label.",
  durationInFrames: 90,
};

export const schema = {
  x:     { type: "number", default: 0.62, min: 0, max: 1, step: 0.01 },
  y:     { type: "number", default: 0.4,  min: 0, max: 1, step: 0.01 },
  label: { type: "string", default: "Click here first" },
  color: { type: "color",  default: "#ff3b30" },
};

export function render(frame, props, ctx) {
  const u = Math.min(ctx.width, ctx.height) / 1080;
  const cx = props.x * ctx.width;
  const cy = props.y * ctx.height;
  const r = 110 * u;
  const circumference = 2 * Math.PI * r;
  const draw = interpolate(frame, [0, 24], [0, 1], { easing: Easing.inOutCubic, clamp: true });
  const arrow = interpolate(frame, [18, 36], [0, 1], { easing: Easing.outBack, clamp: true });
  const labelIn = spring({ frame: frame - 30, fps: ctx.fps, damping: 15 });
  const ax = cx - r * 0.75;
  const ay = cy + r * 0.75;
  const tailX = ax - 260 * u;
  const tailY = ay + 200 * u;
  const hx = tailX + (ax - tailX) * arrow;
  const hy = tailY + (ay - tailY) * arrow;
  const angle = Math.atan2(ay - tailY, ax - tailX);
  const head = 34 * u;
  const p1 = `${hx - head * Math.cos(angle - 0.45)},${hy - head * Math.sin(angle - 0.45)}`;
  const p2 = `${hx - head * Math.cos(angle + 0.45)},${hy - head * Math.sin(angle + 0.45)}`;
  const stroke = 10 * u;
  return svg(ctx, `
    <circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${props.color}" stroke-width="${stroke}"
            stroke-linecap="round" stroke-dasharray="${circumference}"
            stroke-dashoffset="${circumference * (1 - draw)}" transform="rotate(-90 ${cx} ${cy})"/>
    <g opacity="${arrow > 0 ? 1 : 0}">
      <line x1="${tailX}" y1="${tailY}" x2="${hx}" y2="${hy}" stroke="${props.color}" stroke-width="${stroke}"
            stroke-linecap="round"/>
      <polygon points="${hx},${hy} ${p1} ${p2}" fill="${props.color}"/>
    </g>
    <text x="${tailX}" y="${tailY + 70 * u}" text-anchor="middle" font-family="Darker Grotesque" font-weight="800"
          font-size="${64 * u}" fill="#ffffff" stroke="#000000" stroke-width="${2 * u}"
          opacity="${Math.max(0, Math.min(1, labelIn))}">${escapeXml(props.label)}</text>`);
}
// chapter-card — a bundled template (spec §11 G-44): a full card with a
// large outlined chapter numeral, a kicker whose spacing settles, an accent
// rule drawing across and the title revealed upward.
export const meta = {
  name: "Chapter card",
  category: "Titles & Text",
  description: "A full card with a large chapter number and a title.",
  durationInFrames: 120,
};

export const schema = {
  number:     { type: "number", default: 1, min: 0, max: 99, step: 1, animate: false },
  kicker:     { type: "string", default: "CHAPTER" },
  title:      { type: "string", default: "Getting started" },
  background: { type: "color",  default: "#0b0b10" },
  accent:     { type: "color",  default: "#ff5a36" },
};

export function render(frame, props, ctx) {
  const u = Math.min(ctx.width, ctx.height) / 1080;
  const D = ctx.durationInFrames;
  const safeX = ctx.width * 0.05;
  const safeW = ctx.width * 0.9;
  const pad = 70 * u;
  const left = safeX + pad;
  const width = safeW - 2 * pad;
  const numeral = String(Math.max(0, Math.min(99, Math.round(props.number)))).padStart(2, "0");
  const numSize = 300 * u;
  const numFont = { family: "Montserrat", size: numSize, weight: 900 };
  const numW = measureText(numeral, numFont).width;
  const titleSize = fitText(props.title, width, { family: "Montserrat", weight: 900 }, { min: 16 * u, max: 150 * u });
  const kickerSize = 44 * u;
  const blockH = numSize * 0.74 + 60 * u + titleSize * 0.74 + 40 * u;
  const top = (ctx.height - blockH) / 2;
  const numBase = top + numSize * 0.74;
  const ruleY = numBase + 46 * u;
  const titleBase = ruleY + 34 * u + titleSize * 0.74;
  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
  const lift = interpolate(frame, [D - 15, D - 1], [0, -24 * u], { easing: Easing.inCubic, clamp: true });
  const numIn = interpolate(frame, [0, 22], [0, 1], { easing: Easing.outCubic, clamp: true });
  const numScale = 1.15 - 0.15 * numIn;
  const kickIn = interpolate(frame, [8, 30], [0, 1], { easing: Easing.outCubic, clamp: true });
  const rule = interpolate(frame, [14, 38], [0, 1], { easing: Easing.inOutCubic, clamp: true });
  const reveal = interpolate(frame, [22, 46], [0, 1], { easing: Easing.outCubic, clamp: true });
  const kickerX = left + numW + 40 * u;
  const kickerMax = left + width - kickerX;
  // The kicker wraps beside the numeral, at most three lines at its widest spacing, shrinking (its
  // spacing in proportion) until it does and until every word fits its room, so a line only ever
  // breaks between words.
  const kickerWords = props.kicker.split(/\s+/).filter((word) => word);
  let kickerFit = kickerSize;
  let kickerLines = [];
  for (;;) {
    const font = { family: "Montserrat", size: kickerFit, weight: 800, letterSpacing: (22 * u * kickerFit) / kickerSize };
    kickerLines = kickerWords.length ? wrapText(props.kicker, kickerMax, font) : [];
    const wordsFit = kickerWords.every((word) => measureText(word, font).width <= kickerMax);
    if ((kickerLines.length <= 3 && wordsFit) || kickerFit <= 10 * u) break;
    kickerFit = Math.max(10 * u, kickerFit * 0.9);
  }
  const spacing = ((22 - 14 * kickIn) * u * kickerFit) / kickerSize;
  const kickerLead = kickerFit * 1.2;
  const kickerTop = numBase - numSize * 0.37 + kickerFit * 0.36 - ((kickerLines.length - 1) * kickerLead) / 2;
  const ncx = left + numW / 2;
  const ncy = numBase - numSize * 0.37;
  const ruleW = width * rule;
  const rise = (1 - reveal) * titleSize * 1.15;
  return svg(ctx, `
    <defs>
      <clipPath id="title"><rect x="${safeX}" y="${ruleY + 10 * u}" width="${safeW}" height="${titleBase - ruleY - 10 * u + titleSize * 0.26}"/></clipPath>
    </defs>
    <g transform="translate(0 ${lift})">
      <g transform="translate(${ncx} ${ncy}) scale(${numScale}) translate(${-ncx} ${-ncy})">
        <text x="${left}" y="${numBase}" font-family="Montserrat" font-weight="900" font-size="${numSize}" fill="none"
              stroke="${props.accent}" stroke-width="${4 * u}" stroke-opacity="${numIn * out}">${numeral}</text>
      </g>
      <text x="${kickerX}" y="${kickerTop}" font-family="Montserrat" font-weight="800"
            font-size="${kickerFit}" letter-spacing="${spacing}" fill="#d8d8e0"
            fill-opacity="${kickIn * out}">${kickerLines.map((line, i) =>
              `<tspan x="${kickerX}" y="${kickerTop + i * kickerLead}">${escapeXml(line)}</tspan>`).join("")}</text>
      ${ruleW > 0.5 ? `<rect x="${left}" y="${ruleY}" width="${ruleW}" height="${6 * u}" fill="${props.accent}"
            fill-opacity="${out}"/>` : ""}
      <g clip-path="url(#title)">
        <text x="${left}" y="${titleBase + rise}" font-family="Montserrat" font-weight="900" font-size="${titleSize}"
              fill="#ffffff" fill-opacity="${out}">${escapeXml(props.title)}</text>
      </g>
    </g>`, { background: props.background });
}
// countdown — a bundled template (spec §11 G-44): a timer counting from
// `from` to `to` one step a second (up when `to` is greater), its digits
// pulsing on each tick inside a ring that empties or fills, and a flash at
// the end.
export const meta = {
  name: "Countdown",
  category: "Data & Time",
  description: "A timer counting down or up inside a ring, flashing at the end.",
  durationInFrames: 330,
};

export const schema = {
  from:   { type: "number",  default: 10 },
  to:     { type: "number",  default: 0 },
  format: { type: "enum",    default: "m:ss", options: ["seconds", "m:ss", "h:mm:ss"] },
  label:  { type: "string",  default: "Starting in" },
  ring:   { type: "boolean", default: true },
  accent: { type: "color",   default: "#ff5a36" },
};

function clock(n, format) {
  const sign = n < 0 ? "-" : "";
  const s = Math.abs(n);
  const two = (v) => String(v).padStart(2, "0");
  if (format === "seconds") return sign + s;
  if (format === "h:mm:ss") return `${sign}${Math.floor(s / 3600)}:${two(Math.floor(s / 60) % 60)}:${two(s % 60)}`;
  return `${sign}${Math.floor(s / 60)}:${two(s % 60)}`;
}

export function render(frame, props, ctx) {
  const u = Math.min(ctx.width, ctx.height) / 1080;
  const D = ctx.durationInFrames;
  const from = Math.round(props.from);
  const to = Math.round(props.to);
  const steps = Math.abs(to - from);
  const t = Math.max(0, ctx.time);
  const ticked = Math.min(steps, Math.floor(t));
  const n = to < from ? from - ticked : from + ticked;
  const done = t >= steps;
  const cx = ctx.width / 2;
  const cy = ctx.height / 2;
  const R = 300 * u;
  const thick = 22 * u;
  const enter = spring({ frame, fps: ctx.fps, stiffness: 140, damping: 15 });
  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
  const local = t - Math.floor(t);
  const pulse = done && t - steps > 0.3 ? 1 : interpolate(local, [0, 0.3], [1.08, 1], { easing: Easing.outCubic, clamp: true });
  // From equal to `to` there is nothing to count: the ring stands at its end state and nothing flashes.
  const left = steps === 0 ? 0 : Math.max(0, Math.min(1, 1 - t / steps));
  const ringShown = to < from ? left : 1 - left;
  const text = clock(n, props.format);
  const widest = clock(from, props.format).length >= clock(to, props.format).length
    ? clock(from, props.format) : clock(to, props.format);
  const digitSize = fitText(widest.replace(/[0-9]/g, "0"), R * 1.45, { family: "IBM Plex Mono", weight: 500 },
    { min: 12 * u, max: 190 * u });
  const flash = done && steps > 0 ? interpolate(t - steps, [0, 0.6], [0.85, 0], { easing: Easing.outCubic, clamp: true }) : 0;
  const labelText = props.label.toUpperCase();
  const labelSize = fitText(labelText, R * 1.3, { family: "Montserrat", weight: 800, letterSpacing: 5 * u },
    { min: 10 * u, max: 34 * u });
  const circumference = 2 * Math.PI * R;
  return svg(ctx, `
    <g opacity="${out * Math.min(1, enter * 1.4)}"
       transform="translate(${cx} ${cy}) scale(${0.85 + 0.15 * enter}) translate(${-cx} ${-cy})">
      <circle cx="${cx}" cy="${cy}" r="${R + thick / 2 + 8 * u}" fill="#101014" fill-opacity="0.82"/>
      ${flash > 0 ? `<circle cx="${cx}" cy="${cy}" r="${R + thick / 2 + 8 * u}" fill="${props.accent}" fill-opacity="${flash}"/>` : ""}
      ${props.ring ? `
      <circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="#ffffff" stroke-opacity="0.12" stroke-width="${thick}"/>
      ${ringShown > 0.0005 ? `<circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="${props.accent}"
              stroke-width="${thick}" stroke-linecap="round" stroke-dasharray="${circumference * ringShown} ${circumference}"
              transform="rotate(-90 ${cx} ${cy})"/>` : ""}` : ""}
      <text x="${cx}" y="${cy - digitSize * 0.62}" text-anchor="middle" font-family="Montserrat" font-weight="800"
            font-size="${labelSize}" letter-spacing="${5 * u}" fill="#d8d8e0">${escapeXml(labelText)}</text>
      <g transform="translate(${cx} ${cy + digitSize * 0.12}) scale(${pulse})">
        <text x="0" y="${digitSize * 0.35}" text-anchor="middle" font-family="IBM Plex Mono" font-weight="500"
              font-size="${digitSize}" fill="#ffffff">${escapeXml(text)}</text>
      </g>
    </g>`);
}
// counter — road map 10 §5k 3: a number counting from `from` to `to` with a
// thousands separator, in IBM Plex Mono.
export const meta = {
  name: "Counter",
  category: "Data & Time",
  description: "A number counting up, with a prefix and a label.",
  durationInFrames: 90,
};

export const schema = {
  from:   { type: "number", default: 0 },
  to:     { type: "number", default: 1284093 },
  prefix: { type: "string", default: "$" },
  label:  { type: "string", default: "raised this year" },
  color:  { type: "color",  default: "#f5f5f0" },
};

export function render(frame, props, ctx) {
  const u = Math.min(ctx.width, ctx.height) / 1080;
  const end = Math.max(1, Math.round(ctx.durationInFrames * 0.7));
  const value = interpolate(frame, [0, end], [props.from, props.to], { easing: Easing.outExpo, clamp: true });
  const text = props.prefix + formatNumber(value);
  const size = 150 * u;
  const pop = spring({ frame, fps: ctx.fps, stiffness: 180, damping: 18 });
  return svg(ctx, `
    <g transform="translate(${ctx.width / 2} ${ctx.height / 2}) scale(${0.8 + 0.2 * pop})">
      <text x="0" y="${size * 0.3}" text-anchor="middle" font-family="IBM Plex Mono" font-weight="500"
            font-size="${size}" fill="${props.color}">${escapeXml(text)}</text>
      <text x="0" y="${size * 0.3 + 80 * u}" text-anchor="middle" font-family="IBM Plex Mono"
            font-weight="400" font-size="${40 * u}" fill="${props.color}" opacity="0.7">${escapeXml(props.label)}</text>
    </g>`);
}

1	// donut-chart — a bundled template (spec §11 G-44): `values` as a
2	// comma-separated string, slices sweeping clockwise in turn, the first
3	// slice's share counting up in the centre and a staggered legend.
4	export const meta = {
5	  name: "Donut chart",
6	  category: "Data & Time",
7	  description: "Slices sweeping round a donut, a share and a legend.",
8	  durationInFrames: 150,
9	};
10	
11	export const schema = {
12	  values: { type: "string", default: "45, 30, 15, 10", animate: false },
13	  labels: { type: "string", default: "Video, Audio, Graphics, Other", animate: false },
14	  title:  { type: "string", default: "Where the time goes" },
15	  accent: { type: "color",  default: "#ff5a36" },
16	};
17	
18	const PALETTE = ["#2d7ff9", "#ffd60a", "#34c759", "#af52de", "#ff9f0a", "#5ac8fa"];
19	
20	// An arc of the circle (cx, cy, r) from angle a0 to a1, in degrees clockwise
21	// from twelve o'clock; a full turn is two half arcs.
22	function arc(cx, cy, r, a0, a1) {
23	  const at = (a) => {
24	    const t = ((a - 90) * Math.PI) / 180;
25	    return `${cx + r * Math.cos(t)} ${cy + r * Math.sin(t)}`;
26	  };
27	  if (a1 - a0 >= 359.99) {
28	    return `M ${at(a0)} A ${r} ${r} 0 1 1 ${at(a0 + 180)} A ${r} ${r} 0 1 1 ${at(a0 + 359.99)}`;
29	  }
30	  return `M ${at(a0)} A ${r} ${r} 0 ${a1 - a0 > 180 ? 1 : 0} 1 ${at(a1)}`;
31	}
32	
33	export function render(frame, props, ctx) {
34	  const u = Math.min(ctx.width, ctx.height) / 1080;
35	  const D = ctx.durationInFrames;
36	  const values = props.values.split(",").map((v) => Number(v.trim())).filter((v) => isFinite(v))
37	    .map((v) => Math.max(0, v));
38	  const labels = props.labels.split(",").map((l) => l.trim());
39	  const n = values.length;
40	  const total = values.reduce((a, b) => a + b, 0);
41	  // A square frame takes the side-by-side layout: a column would not fit its height.
42	  const landscape = ctx.width >= ctx.height;
43	  const safeX = ctx.width * 0.05;
44	  const safeY = ctx.height * 0.05;
45	  const safeW = ctx.width * 0.9;
46	  const safeH = ctx.height * 0.9;
47	  const pad = 60 * u;
48	  const innerW = safeW - 2 * pad;
49	  const titleSize = fitText(props.title, innerW, { family: "Montserrat", weight: 900 }, { min: 12 * u, max: 64 * u });
50	  const rowH = Math.min(78 * u, (landscape ? safeH - 300 * u : 560 * u) / Math.max(1, n));
51	  const legendH = rowH * n;
52	  const thick = 64 * u;
53	  let legendW = Math.min(620 * u, innerW);
54	  let R;
55	  let cx;
56	  let cy;
57	  let legendX;
58	  let legendY;
59	  let blockTop;
60	  if (landscape) {
61	    // The donut leaves the legend at least 360u beside it (a square frame's narrow width).
62	    const gapL = Math.min(140 * u, innerW * 0.1);
63	    R = Math.min((safeH - 2 * pad - titleSize - 100 * u) / 2 - thick / 2, innerW * 0.22,
64	      (innerW - thick - gapL - 360 * u) / 2);
65	    legendW = Math.min(620 * u, innerW - 2 * R - thick - gapL);
66	    blockTop = safeY + Math.max(pad, (safeH - (titleSize + 70 * u + 2 * R + thick)) / 2);
67	    const blockW = 2 * R + thick + gapL + legendW;
68	    cx = Math.max(safeX + pad, (ctx.width - blockW) / 2) + thick / 2 + R;
69	    cy = blockTop + titleSize + 70 * u + thick / 2 + R;
70	    legendX = cx + R + thick / 2 + gapL;
71	    legendY = cy - legendH / 2;
72	  } else {
73	    R = innerW * 0.3;
74	    const blockH = titleSize + 80 * u + 2 * R + thick + 90 * u + legendH;
75	    blockTop = safeY + Math.max(pad, (safeH - blockH) / 2);
76	    cx = ctx.width / 2;
77	    cy = blockTop + titleSize + 80 * u + thick / 2 + R;
78	    legendX = (ctx.width - legendW) / 2;
79	    legendY = cy + R + thick / 2 + 90 * u;
80	  }
81	  const titleX = landscape ? cx - R - thick / 2 : ctx.width / 2;
82	  const titleFits = landscape
83	    ? Math.min(titleSize, fitText(props.title, safeX + safeW - pad - titleX, { family: "Montserrat", weight: 900 },
84	      { min: 12 * u, max: 64 * u }))
85	    : titleSize;
86	  const fade = interpolate(frame, [0, 15], [0, 1], { clamp: true });
87	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
88	  const sweep = interpolate(frame, [8, 70], [0, 360], { easing: Easing.inOutCubic, clamp: true });
89	  const gap = n > 1 ? 1.6 : 0;
90	
91	  let slices = `<circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="#ffffff" stroke-opacity="0.08"
92	                        stroke-width="${thick}"/>`;
93	  let start = 0;
94	  values.forEach((v, i) => {
95	    const size = total > 0 ? (v / total) * 360 : 0;
96	    const shown = Math.min(sweep, start + size) - start;
97	    if (size > 0 && shown > gap) {
98	      const colour = i === 0 ? props.accent : PALETTE[(i - 1) % PALETTE.length];
99	      slices += `<path d="${arc(cx, cy, R, start + gap / 2, start + shown - gap / 2)}" fill="none"
100	                       stroke="${colour}" stroke-width="${thick}"/>`;
101	    }
102	    start += size;
103	  });
104	
105	  const share = total > 0 ? (values[0] / total) * 100 : 0;
106	  const counted = share * interpolate(frame, [8, 70], [0, 1], { easing: Easing.inOutCubic, clamp: true });
107	  const percentSize = Math.min(120 * u, R * 0.62);
108	  const centreLabel = labels[0] || "";
109	  const centreSize = centreLabel ? fitText(centreLabel, (2 * R - thick) * 0.8, { family: "Montserrat", weight: 800 },
110	    { min: 8 * u, max: 28 * u }) : 28 * u;
111	  const centre = `
112	    <text x="${cx}" y="${cy + percentSize * 0.3}" text-anchor="middle" font-family="IBM Plex Mono"
113	          font-weight="500" font-size="${percentSize}" fill="#ffffff">${Math.round(counted)}%</text>
114	    <text x="${cx}" y="${cy + percentSize * 0.3 + 52 * u}" text-anchor="middle" font-family="Montserrat"
115	          font-weight="800" font-size="${centreSize}" fill="#c8c8d0" opacity="${fade}">${escapeXml(centreLabel)}</text>`;
116	
117	  let legend = "";
118	  // One size for every row's label, the smallest any needs to clear the widest percentage.
119	  const rowSize = Math.min(36 * u, rowH * 0.5);
120	  const sq = rowSize * 0.8;
121	  const pcts = values.map((v) => (total > 0 ? `${Math.round((v / total) * 100)}%` : "0%"));
122	  const pctW = Math.max(0, ...pcts.map((p) => measureText(p, { family: "IBM Plex Mono", size: rowSize, weight: 500 }).width));
123	  const labelRoom = legendW - sq - 22 * u - pctW - 24 * u;
124	  const labelSize = Math.min(rowSize, ...labels.slice(0, n).filter((l) => l).map((l) =>
125	    fitText(l, labelRoom, { family: "Montserrat", weight: 800 }, { min: 8 * u, max: rowSize })));
126	  values.forEach((v, i) => {
127	    const t = spring({ frame: frame - 24 - i * 6, fps: ctx.fps, damping: 16 });
128	    if (t <= 0.001) return;
129	    const colour = i === 0 ? props.accent : PALETTE[(i - 1) % PALETTE.length];
130	    const y = legendY + rowH * i + rowH / 2;
131	    legend += `<g opacity="${Math.min(1, t)}" transform="translate(${(1 - Math.min(1, t)) * 30 * u} 0)">
132	      <rect x="${legendX}" y="${y - sq / 2}" width="${sq}" height="${sq}" rx="${sq * 0.2}" fill="${colour}"/>
133	      <text x="${legendX + sq + 22 * u}" y="${y + labelSize * 0.36}" font-family="Montserrat" font-weight="800"
134	            font-size="${labelSize}" fill="#ffffff">${escapeXml(labels[i] || "")}</text>
135	      <text x="${legendX + legendW}" y="${y + rowSize * 0.36}" text-anchor="end" font-family="IBM Plex Mono"
136	            font-weight="500" font-size="${rowSize}" fill="#c8c8d0">${pcts[i]}</text></g>`;
137	  });
138	
139	  return svg(ctx, `
140	    <g opacity="${out}">
141	      <text x="${titleX}" y="${blockTop + titleSize * 0.8}" text-anchor="${landscape ? "start" : "middle"}"
142	            font-family="Montserrat" font-weight="900" font-size="${titleFits}" fill="#ffffff"
143	            opacity="${fade}">${escapeXml(props.title)}</text>
144	      ${slices}${centre}${legend}
145	    </g>`, { background: "#15151b" });
146	}
147	// end-screen — a bundled template (spec §11 G-44): a full card laid out for
148	// a video's end screen — two 16:9 placeholders where the platform's video
149	// elements go and a subscribe circle — the two side by side with the circle
150	// centred under them in landscape and square, a column in portrait, under a title.
151	export const meta = {
152	  name: "End screen",
153	  category: "Social & YouTube",
154	  description: "An end screen card with two video spaces and a subscribe circle.",
155	  durationInFrames: 300,
156	};
157	
158	export const schema = {
159	  title:      { type: "string", default: "Watch next" },
160	  videoA:     { type: "string", default: "Latest video" },
161	  videoB:     { type: "string", default: "Best for you" },
162	  subscribe:  { type: "string", default: "Subscribe" },
163	  background: { type: "color",  default: "#0b0b10" },
164	  accent:     { type: "color",  default: "#ff5a36" },
165	};
166	
167	export function render(frame, props, ctx) {
168	  const u = Math.min(ctx.width, ctx.height) / 1080;
169	  const D = ctx.durationInFrames;
170	  const W = ctx.width;
171	  const H = ctx.height;
172	  // A square frame takes the landscape layout: a portrait column would not fit its height.
173	  const landscape = W >= H;
174	  const safeX = W * 0.05;
175	  const safeY = H * 0.05;
176	  const safeW = W * 0.9;
177	  const safeH = H * 0.9;
178	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
179	  const titleSize = props.title ? fitText(props.title, safeW - 120 * u, { family: "Montserrat", weight: 900 },
180	    { min: 16 * u, max: (landscape ? 96 : 84) * u }) : 0;
181	  const labelFont = { family: "Montserrat", size: (landscape ? 38 : 34) * u, weight: 800 };
182	  const gap = (landscape ? 64 : 48) * u;
183	  const labelH = 70 * u;
184	  let boxW;
185	  let boxH;
186	  let circleD;
187	  let boxes;
188	  let circle;
189	  let titleY;
190	  if (landscape) {
191	    // YouTube's "two videos and a subscribe" layout: the two videos side by side, each about a
192	    // third of the frame's width, and the subscribe circle centred under them at about two
193	    // thirds of a video's height, everything held to the safe width and height.
194	    const titleGap = 56 * u;
195	    const circleGap = 24 * u;
196	    const fromHeight = ((safeH - 40 * u - titleSize - titleGap - 2 * labelH - circleGap) / 1.62) * (16 / 9);
197	    // 20u spare at each side holds the dashed outline and the entrance spring's overshoot.
198	    boxW = Math.max(0, Math.min(W * (W > H ? 0.34 : 0.42), (safeW - gap - 40 * u) / 2, fromHeight));
199	    boxH = (boxW * 9) / 16;
200	    circleD = boxH * 0.62;
201	    const blockH = titleSize + titleGap + boxH + labelH + circleGap + circleD + labelH;
202	    const top = safeY + (safeH - blockH) / 2;
203	    titleY = top + titleSize * 0.8;
204	    const rowTop = top + titleSize + titleGap;
205	    const x = (W - 2 * boxW - gap) / 2;
206	    boxes = [
207	      { x, y: rowTop, label: props.videoA },
208	      { x: x + boxW + gap, y: rowTop, label: props.videoB },
209	    ];
210	    circle = { cx: W / 2, cy: rowTop + boxH + labelH + circleGap + circleD / 2 };
211	  } else {
212	    boxW = W * 0.8;
213	    boxH = (boxW * 9) / 16;
214	    circleD = 260 * u;
215	    const blockH = titleSize + 60 * u + 2 * (boxH + labelH) + gap + circleD + labelH;
216	    const top = safeY + (safeH - blockH) / 2;
217	    titleY = top + titleSize * 0.8;
218	    const x = (W - boxW) / 2;
219	    const first = top + titleSize + 60 * u;
220	    boxes = [
221	      { x, y: first, label: props.videoA },
222	      { x, y: first + boxH + labelH + gap / 2, label: props.videoB },
223	    ];
224	    circle = { cx: W / 2, cy: first + 2 * (boxH + labelH) + gap + circleD / 2 };
225	  }
226	  const titleIn = interpolate(frame, [0, 16], [0, 1], { easing: Easing.outCubic, clamp: true });
227	  let body = props.title ? `<text x="${W / 2}" y="${titleY + (1 - titleIn) * 20 * u}" text-anchor="middle"
228	    font-family="Montserrat" font-weight="900" font-size="${titleSize}" fill="#ffffff"
229	    fill-opacity="${titleIn * out}">${escapeXml(props.title)}</text>` : "";
230	  boxes.forEach((b, i) => {
231	    const t = spring({ frame: frame - 8 - i * 6, fps: ctx.fps, stiffness: 150, damping: 15 });
232	    if (t <= 0.001) return;
233	    const a = Math.min(1, t) * out;
234	    const cx = b.x + boxW / 2;
235	    const cy = b.y + boxH / 2;
236	    const s = 0.9 + 0.1 * t;
237	    const g = boxH * 0.2;
238	    const size = Math.min(labelFont.size, fitText(b.label || " ", boxW, labelFont, { min: 10 * u, max: labelFont.size }));
239	    body += `<g transform="translate(${cx} ${cy}) scale(${s}) translate(${-cx} ${-cy})">
240	      <rect x="${b.x}" y="${b.y}" width="${boxW}" height="${boxH}" rx="${14 * u}" fill="#ffffff" fill-opacity="${0.06 * a}"
241	            stroke="#ffffff" stroke-opacity="${0.55 * a}" stroke-width="${3 * u}" stroke-dasharray="${16 * u} ${10 * u}"/>
242	      <circle cx="${cx}" cy="${cy}" r="${g}" fill="${props.accent}" fill-opacity="${a}"/>
243	      <path d="M ${cx - g * 0.32} ${cy - g * 0.45} L ${cx + g * 0.5} ${cy} L ${cx - g * 0.32} ${cy + g * 0.45} Z"
244	            fill="#ffffff" fill-opacity="${a}"/>
245	      <text x="${cx}" y="${b.y + boxH + (landscape ? 50 : 46) * u}" text-anchor="middle" font-family="Montserrat" font-weight="800"
246	            font-size="${size}" fill="#d8d8e0" fill-opacity="${a}">${escapeXml(b.label)}</text></g>`;
247	  });
248	  const pop = spring({ frame: frame - 24, fps: ctx.fps, stiffness: 190, damping: 12 });
249	  if (pop > 0.001) {
250	    const r = circleD / 2;
251	    const pulse = interpolate(frame, [40, 70], [0, 1], { easing: Easing.outCubic, clamp: true });
252	    const a = out;
253	    const size = Math.min(labelFont.size, fitText(props.subscribe || " ", Math.max(circleD, 200 * u), labelFont,
254	      { min: 10 * u, max: labelFont.size }));
255	    const head = r * 0.3;
256	    body += `<g transform="translate(${circle.cx} ${circle.cy}) scale(${pop})">
257	      ${pulse > 0 && pulse < 1 ? `<circle cx="0" cy="0" r="${r + 26 * u * pulse}" fill="none" stroke="${props.accent}"
258	              stroke-width="${4 * u}" stroke-opacity="${(1 - pulse) * a}"/>` : ""}
259	      <circle cx="0" cy="0" r="${r}" fill="#ffffff" fill-opacity="${0.06 * a}" stroke="${props.accent}"
260	              stroke-opacity="${a}" stroke-width="${5 * u}" stroke-dasharray="${16 * u} ${10 * u}"/>
261	      <circle cx="0" cy="${-head * 0.62}" r="${head}" fill="#8a8a94" fill-opacity="${a}"/>
262	      <path d="M ${-r * 0.5} ${r * 0.55} C ${-r * 0.5} ${r * 0.1} ${-r * 0.25} ${r * 0.0} 0 ${r * 0.0}
263	               C ${r * 0.25} ${r * 0.0} ${r * 0.5} ${r * 0.1} ${r * 0.5} ${r * 0.55} Z" fill="#8a8a94" fill-opacity="${a}"/>
264	      <text x="0" y="${r + 46 * u}" text-anchor="middle" font-family="Montserrat" font-weight="800" font-size="${size}"
265	            fill="#ffffff" fill-opacity="${a}">${escapeXml(props.subscribe)}</text></g>`;
266	  }
267	  return svg(ctx, body, { background: props.background });
268	}
269	// gauge — a bundled template (spec §11 G-44): a 270° dial with ticks, an
270	// accent arc and a needle that swing from `min` to `value` on a spring, and
271	// the value counting in the dial's open foot.
272	export const meta = {
273	  name: "Gauge",
274	  category: "Data & Time",
275	  description: "A dial whose needle swings to a value, the value counting.",
276	  durationInFrames: 120,
277	};
278	
279	export const schema = {
280	  value:  { type: "number", default: 72 },
281	  min:    { type: "number", default: 0 },
282	  max:    { type: "number", default: 100 },
283	  label:  { type: "string", default: "Speed" },
284	  units:  { type: "string", default: "km/h" },
285	  accent: { type: "color",  default: "#ff5a36" },
286	};
