288	// The point at `r` from (cx, cy) at `deg` clockwise from twelve o'clock.
289	function polar(cx, cy, r, deg) {
290	  const t = ((deg - 90) * Math.PI) / 180;
291	  return { x: cx + r * Math.cos(t), y: cy + r * Math.sin(t) };
292	}
293	
294	function arc(cx, cy, r, a0, a1) {
295	  const p = polar(cx, cy, r, a0);
296	  const q = polar(cx, cy, r, a1);
297	  return `M ${p.x} ${p.y} A ${r} ${r} 0 ${a1 - a0 > 180 ? 1 : 0} 1 ${q.x} ${q.y}`;
298	}
299	
300	export function render(frame, props, ctx) {
301	  const u = Math.min(ctx.width, ctx.height) / 1080;
302	  const D = ctx.durationInFrames;
303	  const min = props.min;
304	  const max = props.max > min ? props.max : min + 1;
305	  const value = Math.min(max, Math.max(min, props.value));
306	  const cx = ctx.width / 2;
307	  const cy = ctx.height / 2;
308	  const R = 300 * u;
309	  const disc = R * 1.22;
310	  const thick = 30 * u;
311	  const enter = spring({ frame, fps: ctx.fps, stiffness: 140, damping: 16 });
312	  const out = interpolate(frame, [D - 15, D - 1], [0, 1], { easing: Easing.inCubic, clamp: true });
313	  const scale = (0.9 + 0.1 * Math.min(1, enter)) * (1 - 0.1 * out);
314	  const opacity = Math.min(1, enter * 1.4) * (1 - out);
315	  const swing = spring({ frame: frame - 10, fps: ctx.fps, stiffness: 55, damping: 8 });
316	  const fraction = (value - min) / (max - min);
317	  const shown = Math.max(0, Math.min(1.04, fraction * swing));
318	  const angle = -135 + 270 * shown;
319	
320	  let ticks = "";
321	  for (let i = 0; i <= 40; i++) {
322	    const a = -135 + (270 * i) / 40;
323	    const major = i % 4 === 0;
324	    const p = polar(cx, cy, R - thick / 2 - 18 * u, a);
325	    const q = polar(cx, cy, R - thick / 2 - (major ? 48 : 30) * u, a);
326	    ticks += `<line x1="${p.x}" y1="${p.y}" x2="${q.x}" y2="${q.y}" stroke="#ffffff"
327	                    stroke-opacity="${major ? 0.75 : 0.3}" stroke-width="${(major ? 5 : 3) * u}" stroke-linecap="round"/>`;
328	  }
329	  const decimals = Number.isInteger(props.value) ? 0 : 1;
330	  const counted = min + (value - min) * Math.max(0, Math.min(1, swing));
331	  const text = formatNumber(counted, { decimals });
332	  const valueSize = fitText(text, R * 0.95, { family: "IBM Plex Mono", weight: 500 }, { min: 12 * u, max: 128 * u });
333	  const tip = polar(cx, cy, R - thick / 2 - 6 * u, angle);
334	  const left = polar(cx, cy, 16 * u, angle - 90);
335	  const right = polar(cx, cy, 16 * u, angle + 90);
336	  const tail = polar(cx, cy, 40 * u, angle + 180);
337	  const labelSize = fitText(props.label.toUpperCase(), R, { family: "Montserrat", weight: 800, letterSpacing: 4 * u },
338	    { min: 10 * u, max: 34 * u });
339	  return svg(ctx, `
340	    <g opacity="${opacity}" transform="translate(${cx} ${cy}) scale(${scale}) translate(${-cx} ${-cy})">
341	      <circle cx="${cx}" cy="${cy}" r="${disc}" fill="#101014" fill-opacity="0.82"/>
342	      <path d="${arc(cx, cy, R, -135, 135)}" fill="none" stroke="#ffffff" stroke-opacity="0.12"
343	            stroke-width="${thick}" stroke-linecap="round"/>
344	      ${shown > 0.001 ? `<path d="${arc(cx, cy, R, -135, -135 + 270 * Math.min(1, shown))}" fill="none"
345	            stroke="${props.accent}" stroke-width="${thick}" stroke-linecap="round"/>` : ""}
346	      ${ticks}
347	      <text x="${cx}" y="${cy - R * 0.38}" text-anchor="middle" font-family="Montserrat" font-weight="800"
348	            font-size="${labelSize}" letter-spacing="${4 * u}" fill="#d8d8e0">${escapeXml(props.label.toUpperCase())}</text>
349	      <polygon points="${tip.x},${tip.y} ${left.x},${left.y} ${tail.x},${tail.y} ${right.x},${right.y}"
350	               fill="${props.accent}"/>
351	      <circle cx="${cx}" cy="${cy}" r="${24 * u}" fill="#ffffff"/>
352	      <circle cx="${cx}" cy="${cy}" r="${9 * u}" fill="#101014"/>
353	      <text x="${cx}" y="${cy + R * 0.66}" text-anchor="middle" font-family="IBM Plex Mono" font-weight="500"
354	            font-size="${valueSize}" fill="#ffffff">${escapeXml(text)}</text>
355	      <text x="${cx}" y="${cy + R * 0.66 + 54 * u}" text-anchor="middle" font-family="Montserrat" font-weight="800"
356	            font-size="${34 * u}" fill="#d8d8e0">${escapeXml(props.units)}</text>
357	    </g>`);
358	}
359	// handle-tag — a bundled template (spec §11 G-44): an accent tile holding a
360	// generic vector glyph pops in at a corner, and a pill with the @handle
361	// expands from behind it. No platform's own mark is drawn.
362	export const meta = {
363	  name: "Handle tag",
364	  category: "Social & YouTube",
365	  description: "An @handle in a pill beside a glyph tile, at a corner.",
366	  durationInFrames: 120,
367	};
