369	export const schema = {
370	  handle:   { type: "string", default: "@framejob" },
371	  glyph:    { type: "enum",   default: "play", options: ["play", "camera", "bubble", "note", "globe"] },
372	  position: { type: "enum",   default: "bottom-left", options: ["bottom-left", "bottom-right", "top-left", "top-right"] },
373	  accent:   { type: "color",  default: "#ff5a36" },
