420	  const ty = bottom ? safeY + safeH - margin - tile : safeY + margin;
421	  const tcx = tx + tile / 2;
422	  const tcy = ty + tile / 2;
423	  const font = { family: "Montserrat", size: 42 * u, weight: 800 };
424	  const maxText = safeW - 2 * margin - tile - 80 * u;
425	  const size = props.handle ? Math.min(font.size, fitText(props.handle, maxText, font, { min: 10 * u, max: font.size })) : font.size;
