493	      M ${s(a)} ${s(e)} A ${s(r)} ${s(r)} 0 1 0 ${s(e)} ${s(a)}
494	      M ${s(-a)} ${s(e)} A ${s(r)} ${s(r)} 0 1 1 ${s(-e)} ${s(a)}
