525	  const capH = 130 * u;
526	  const gap = 22 * u;
527	  const wordFont = { family: "Montserrat", size: 40 * u, weight: 800 };
528	  const charFont = { family: "Montserrat", size: 60 * u, weight: 800 };
529	  const caps = tokens.map((t) => {
530	    const kind = GLYPHS[t.toLowerCase()];
531	    if (kind) return { kind, w: capH };
532	    // The recorder spells the plus key "plus" (spec §11 CU-60, CU-82).
533	    const key = t.toLowerCase() === "plus" ? "+" : t;
534	    const text = key.length === 1 ? key.toUpperCase() : key;
535	    const font = key.length === 1 ? charFont : wordFont;
536	    return { text, font, w: Math.max(capH, measureText(text, font).width + 70 * u) };
537	  });
538	  const rowW = caps.reduce((a, c) => a + c.w, 0) + gap * Math.max(0, caps.length - 1);
539	  const labelFont = { family: "Montserrat", size: 44 * u, weight: 800 };
540	  const labelSize = props.label.trim() ? fitText(props.label, safeW - 140 * u, labelFont, { min: 10 * u, max: labelFont.size }) : 0;
