542	  const fit = Math.min(1, (safeW - 80 * u) / Math.max(1, rowW));
543	  const groupH = capH * fit + (labelH > 0 ? 30 * u + labelH : 0);
544	  const margin = 50 * u;
545	  const top = props.position === "top" ? safeY + margin
546	    : props.position === "center" ? (ctx.height - groupH) / 2
