555	  const out = interpolate(frame, [D - 15, D - 1], [0, 1], { easing: Easing.inCubic, clamp: true });
556	  const outScale = 1 - 0.1 * out;
557	
558	  let row = "";
559	  let x = cx - (rowW * fit) / 2;
560	  const lipH = 12 * u * fit;
561	  caps.forEach((c, i) => {
562	    const w = c.w * fit;
563	    const h = capH * fit;
564	    const s = enter(i);
