380	  const margin = 40 * u;
381	  const right = props.position.endsWith("right");
382	  const bottom = props.position.startsWith("bottom");
383	  const cx = right ? safeX + safeW - margin - R : safeX + margin + R;
384	  const cy = bottom ? safeY + safeH - margin - R : safeY + margin + R;
385	  const n = String(Math.max(0, Math.min(99, Math.round(props.number))));
386	  const numberSize = n.length > 1 ? 58 * u : 68 * u;
387	  const panelH = 88 * u;
