518	  const safeY = ctx.height * 0.05;
519	  const safeH = ctx.height * 0.9;
520	  const dark = props.theme === "dark";
521	  const face = dark ? "#2c2c33" : "#f6f6f8";
522	  const lip = dark ? "#121216" : "#b9b9c4";
523	  const ink = dark ? "#ffffff" : "#1c1c22";
524	  const tokens = props.keys.split("+").map((t) => t.trim()).filter((t) => t.length > 0);
525	  const capH = 130 * u;
526	  const gap = 22 * u;
527	  const wordFont = { family: "Montserrat", size: 40 * u, weight: 800 };
528	  const charFont = { family: "Montserrat", size: 60 * u, weight: 800 };
529	  const caps = tokens.map((t) => {
530	    const kind = GLYPHS[t.toLowerCase()];
531	    if (kind) return { kind, w: capH };
532	    // The recorder spells the plus key "plus" (spec §11 CU-60, CU-82).
533	    const key = t.toLowerCase() === "plus" ? "+" : t;
534	    const text = key.length === 1 ? key.toUpperCase() : key;
535	    const font = key.length === 1 ? charFont : wordFont;
536	    return { text, font, w: Math.max(capH, measureText(text, font).width + 70 * u) };
537	  });
538	  const rowW = caps.reduce((a, c) => a + c.w, 0) + gap * Math.max(0, caps.length - 1);
539	  const labelFont = { family: "Montserrat", size: 44 * u, weight: 800 };
540	  const labelSize = props.label.trim() ? fitText(props.label, safeW - 140 * u, labelFont, { min: 10 * u, max: labelFont.size }) : 0;
541	  const labelH = labelSize > 0 ? labelSize + 56 * u : 0;
542	  const fit = Math.min(1, (safeW - 80 * u) / Math.max(1, rowW));
543	  const groupH = capH * fit + (labelH > 0 ? 30 * u + labelH : 0);
544	  const margin = 50 * u;
545	  const top = props.position === "top" ? safeY + margin
546	    : props.position === "center" ? (ctx.height - groupH) / 2
547	    : safeY + safeH - margin - groupH;
548	  const cx = ctx.width / 2;
549	  const cy = top + groupH / 2;
550	  const enter = (i) => spring({ frame: frame - i * 5, fps: ctx.fps, stiffness: 200, damping: 13 });
551	  // The first keycap presses at 5n + 14 and the last at 10n + 9; with the
552	  // 15-frame exit, Add Shortcut Overlays never makes a clip shorter than
553	  // D_min(n) = 10n + 25 frames (spec §11 CU-80, core/src/cursor_overlays.rs).
554	  const pressAt = caps.length * 5 + 14;
555	  const out = interpolate(frame, [D - 15, D - 1], [0, 1], { easing: Easing.inCubic, clamp: true });
556	  const outScale = 1 - 0.1 * out;
557	
558	  let row = "";
559	  let x = cx - (rowW * fit) / 2;
560	  const lipH = 12 * u * fit;
561	  caps.forEach((c, i) => {
562	    const w = c.w * fit;
563	    const h = capH * fit;
564	    const s = enter(i);
565	    const dip = interpolate(frame - pressAt - i * 5, [0, 3, 10], [0, 6 * u * fit, 0], { clamp: true });
566	    const kx = x + w / 2;
567	    const ky = top + h / 2;
568	    const rx = 0.18 * h;
569	    let mark = "";
570	    if (c.kind) {
571	      mark = `<g transform="translate(${kx} ${ky - lipH / 2 + dip})">${glyph(c.kind, h * 0.5, ink)}</g>`;
572	    } else {
573	      const size = c.font.size * fit;
574	      mark = `<text x="${kx}" y="${ky - lipH / 2 + dip + size * 0.36}" text-anchor="middle" font-family="Montserrat"
575	                    font-weight="800" font-size="${size}" fill="${ink}">${escapeXml(c.text)}</text>`;
576	    }
577	    if (s > 0.001) {
578	      row += `<g transform="translate(${kx} ${ky}) scale(${s}) translate(${-kx} ${-ky})">
579	        <rect x="${x}" y="${top}" width="${w}" height="${h}" rx="${rx}" fill="${lip}"/>
580	        <rect x="${x}" y="${top + dip}" width="${w}" height="${h - lipH}" rx="${rx}" fill="${face}"/>
581	        <rect x="${kx - w * 0.22}" y="${top + h - lipH - 18 * u * fit + dip}" width="${w * 0.44}" height="${5 * u * fit}"
582	              rx="${2.5 * u * fit}" fill="${props.accent}"/>
583	        ${mark}</g>`;
584	    }
585	    x += w + gap * fit;
586	  });
587	
588	  let label = "";
589	  if (labelSize > 0) {
590	    const t = spring({ frame: frame - caps.length * 5 - 4, fps: ctx.fps, damping: 16 });
591	    const lw = measureText(props.label, { family: "Montserrat", size: labelSize, weight: 800 }).width + 64 * u;
592	    const ly = top + capH * fit + 30 * u + (1 - Math.min(1, t)) * 16 * u;
593	    label = `<g opacity="${Math.max(0, Math.min(1, t))}">
594	      <rect x="${cx - lw / 2}" y="${ly}" width="${lw}" height="${labelH}" rx="${labelH / 2}" fill="#101014"
595	            fill-opacity="0.82"/>
596	      <text x="${cx}" y="${ly + labelH / 2 + labelSize * 0.36}" text-anchor="middle" font-family="Montserrat"
597	            font-weight="800" font-size="${labelSize}" fill="#ffffff">${escapeXml(props.label)}</text></g>`;
598	  }
599	  return svg(ctx, `
600	    <g opacity="${1 - out}" transform="translate(${cx} ${cy}) scale(${outScale}) translate(${-cx} ${-cy})">
601	      ${row}${label}
602	    </g>`);
603	}
604	// kinetic-type — road map 10 §5k 5: a sentence shown word by word, each word
605	// scaled in by a spring, wrapped with wrapText.
606	export const meta = {
607	  name: "Kinetic type",
608	  category: "Titles & Text",
609	  description: "A sentence shown word by word, each word springing in.",
610	  durationInFrames: 150,
611	};
612	
613	export const schema = {
614	  text:    { type: "string", default: "Make something people want to watch twice, then cut it in half" },
615	  stagger: { type: "number", default: 4, min: 1, max: 30, step: 1 },
616	  color:   { type: "color",  default: "#ffffff" },
617	  accent:  { type: "color",  default: "#ffd60a" },
618	};
619	
620	export function render(frame, props, ctx) {
621	  const u = Math.min(ctx.width, ctx.height) / 1080;
622	  const font = { family: "Montserrat", size: 110 * u, weight: 900 };
623	  const lines = wrapText(props.text, ctx.width * 0.8, font);
624	  const space = measureText("a a", font).width - measureText("aa", font).width;
625	  const lineHeight = font.size * 1.15;
626	  const firstBaseline = ctx.height / 2 - ((lines.length - 1) * lineHeight) / 2 + font.size * 0.35;
627	  let body = "";
628	  let index = 0;
629	  lines.forEach((line, row) => {
630	    const words = line.split(" ");
631	    const widths = words.map((w) => measureText(w, font).width);
632	    const total = widths.reduce((a, b) => a + b, 0) + space * (words.length - 1);
633	    let x = (ctx.width - total) / 2;
634	    const y = firstBaseline + row * lineHeight;
635	    words.forEach((word, i) => {
636	      const s = spring({ frame: frame - index * props.stagger, fps: ctx.fps, stiffness: 160, damping: 12 });
637	      const cx = x + widths[i] / 2;
638	      const fill = index % 5 === 3 ? props.accent : props.color;
639	      if (s > 0.001) {
640	        body += `<g transform="translate(${cx} ${y}) scale(${s}) translate(${-cx} ${-y})">` +
641	          `<text x="${x}" y="${y}" font-family="Montserrat" font-weight="900" font-size="${font.size}"` +
642	          ` fill="${fill}">${escapeXml(word)}</text></g>`;
643	      }
644	      x += widths[i] + space;
645	      index++;
646	    });
647	  });
648	  return svg(ctx, body, { background: "#0b0b10" });
649	}
650	// line-chart — a bundled template (spec §11 G-44): `values` as a
651	// comma-separated string, a line drawn on through its points, a dot popping
652	// at each, an area fill behind and the last value called out.
653	export const meta = {
654	  name: "Line chart",
655	  category: "Data & Time",
656	  description: "A line drawn through its points, the last value called out.",
657	  durationInFrames: 150,
658	};
659	
660	export const schema = {
661	  values: { type: "string",  default: "12, 18, 15, 26, 22, 34, 41", animate: false },
662	  labels: { type: "string",  default: "Jan, Feb, Mar, Apr, May, Jun, Jul", animate: false },
663	  title:  { type: "string",  default: "Monthly active users" },
664	  area:   { type: "boolean", default: true },
665	  accent: { type: "color",   default: "#2d7ff9" },
666	};
667	
668	export function render(frame, props, ctx) {
669	  const u = Math.min(ctx.width, ctx.height) / 1080;
670	  const D = ctx.durationInFrames;
671	  const values = props.values.split(",").map((v) => Number(v.trim())).filter((v) => isFinite(v));
672	  const labels = props.labels.split(",").map((l) => l.trim());
673	  const n = values.length;
674	  const safeX = ctx.width * 0.05;
675	  const safeY = ctx.height * 0.05;
676	  const safeW = ctx.width * 0.9;
677	  const safeH = ctx.height * 0.9;
678	  const pad = 60 * u;
679	  const innerW = safeW - 2 * pad;
680	  const blockH = Math.min(safeH - 2 * pad, innerW * 1.35);
681	  const top = safeY + (safeH - blockH) / 2;
682	  const titleFont = { family: "Montserrat", weight: 900 };
683	  const titleSize = fitText(props.title, innerW, titleFont, { min: 12 * u, max: 64 * u });
684	  const left = safeX + pad;
685	  const right = left + innerW;
686	  const plotTop = top + titleSize + 110 * u;
687	  const base = top + blockH - 64 * u;
688	  const lo = Math.min(0, ...values);
689	  const hi = Math.max(lo + 1, ...values);
690	  const span = Math.max(1e-9, hi - lo);
691	  const labelFont = { family: "Montserrat", size: 28 * u, weight: 800 };
692	  const inset = Math.max(24 * u, ...labels.slice(0, n).map((l) => measureText(l, labelFont).width / 2 + 4 * u));
693	  const points = values.map((v, i) => ({
694	    x: n === 1 ? (left + right) / 2 : left + inset + ((innerW - 2 * inset) * i) / Math.max(1, n - 1),
695	    y: base - ((v - lo) / span) * (base - plotTop),
696	  }));
697	  const fade = interpolate(frame, [0, 15], [0, 1], { clamp: true });
698	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
699	  const ease = (f) => interpolate(f, [10, 70], [0, 1], { easing: Easing.inOutCubic, clamp: true });
700	  const drawn = ease(frame);
701	  // Opacity per element (fill- and stroke-opacity), so no frame isolates a layer.
702	  const shown = fade * out;
703	
704	  let grid = "";
705	  for (let i = 0; i <= 4; i++) {
706	    const y = base - ((base - plotTop) * i) / 4;
707	    grid += `<line x1="${left}" y1="${y}" x2="${right}" y2="${y}" stroke="#ffffff"
708	                   stroke-opacity="${(i === 0 ? 0.35 : 0.08) * shown}" stroke-width="${(i === 0 ? 3 : 2) * u}"/>`;
709	  }
710	  let axisLabels = "";
711	  points.forEach((p, i) => {
712	    axisLabels += `<text x="${p.x}" y="${base + 46 * u}" text-anchor="middle" font-family="Montserrat"
713	                         font-weight="800" font-size="${labelFont.size}" fill="#c8c8d0" fill-opacity="${shown}">${escapeXml(labels[i] || "")}</text>`;
714	  });
715	
716	  let line = "";
717	  let areaFill = "";
718	  const reach = [0];
719	  if (n > 1) {
720	    let d = `M ${points[0].x} ${points[0].y}`;
721	    let total = 0;
722	    for (let i = 1; i < n; i++) {
723	      const a = points[i - 1];
724	      const b = points[i];
725	      const mid = (a.x + b.x) / 2;
726	      const seg = `C ${mid} ${a.y} ${mid} ${b.y} ${b.x} ${b.y}`;
727	      total += getLength(`M ${a.x} ${a.y} ${seg}`);
728	      reach.push(total);
729	      d += ` ${seg}`;
730	    }
731	    const dash = evolvePath(drawn, d);
732	    line = `<path d="${d}" fill="none" stroke="${props.accent}" stroke-opacity="${out}" stroke-width="${7 * u}" stroke-linecap="round"
733	                  stroke-linejoin="round" stroke-dasharray="${dash.strokeDasharray}"
734	                  stroke-dashoffset="${dash.strokeDashoffset}"/>`;
735	    if (props.area) {
736	      const areaIn = interpolate(frame, [30, 80], [0, 0.25], { easing: Easing.inOutSine, clamp: true });
737	      areaFill = `<path d="${d} L ${points[n - 1].x} ${base} L ${points[0].x} ${base} Z" fill="${props.accent}"
738	                        fill-opacity="${areaIn * out}"/>`;
739	    }
740	    for (let i = 0; i < n; i++) reach[i] = reach[i] / Math.max(1e-9, total);
741	  }
742	  // The frame at which the line reaches point i: the first frame whose eased progress passes it.
743	  const reachFrame = (fraction) => {
744	    for (let f = 10; f <= 70; f++) if (ease(f) >= fraction - 1e-6) return f;
745	    return 70;
746	  };
747	  let dots = "";
748	  points.forEach((p, i) => {
749	    const at = n > 1 ? reachFrame(reach[i]) : 14;
750	    const s = spring({ frame: frame - at, fps: ctx.fps, stiffness: 220, damping: 11 });
751	    if (s <= 0.001) return;
752	    dots += `<circle cx="${p.x}" cy="${p.y}" r="${11 * u * s}" fill="#15151b" fill-opacity="${out}"
753	                     stroke="${props.accent}" stroke-opacity="${out}" stroke-width="${5 * u}"/>`;
754	  });
755	  let callout = "";
756	  if (n > 0) {
757	    const last = points[n - 1];
758	    const at = (n > 1 ? reachFrame(1) : 14) + 4;
759	    const s = spring({ frame: frame - at, fps: ctx.fps, stiffness: 180, damping: 12 });
760	    const text = formatNumber(values[n - 1], { decimals: Number.isInteger(values[n - 1]) ? 0 : 1 });
761	    const font = { family: "Montserrat", size: 34 * u, weight: 800 };
762	    const w = measureText(text, font).width + 36 * u;
763	    const h = 54 * u;
764	    const cx = Math.min(right - w / 2, Math.max(left + w / 2, last.x));
765	    const cy = last.y - 30 * u - h / 2;
766	    if (s > 0.001) {
767	      callout = `<g transform="translate(${cx} ${cy}) scale(${s})">
768	        <rect x="${-w / 2}" y="${-h / 2}" width="${w}" height="${h}" rx="${h / 2}" fill="${props.accent}" fill-opacity="${out}"/>
769	        <text x="0" y="${12 * u}" text-anchor="middle" font-family="Montserrat" font-weight="800"
770	              font-size="${font.size}" fill="#ffffff" fill-opacity="${out}">${escapeXml(text)}</text></g>`;
771	    }
772	  }
773	  return svg(ctx, `
774	    <text x="${left}" y="${top + titleSize * 0.8}" font-family="Montserrat" font-weight="900"
775	          font-size="${titleSize}" fill="#ffffff" fill-opacity="${shown}">${escapeXml(props.title)}</text>
776	    ${grid}${axisLabels}${areaFill}${line}${dots}${callout}`, { background: "#15151b" });
777	}
778	// logo-reveal — a bundled template (spec §11 G-44): a full card on which an
779	// accent bar sweeps across the centre, wiping in a logo image (or, with none,
780	// a text mark) that settles to size; the bar becomes a rule and a tagline fades up.
781	export const meta = {
782	  name: "Logo reveal",
783	  category: "Titles & Text",
784	  description: "A full card wiping in a logo or text mark, and a tagline.",
785	  durationInFrames: 120,
786	};
787	
788	export const schema = {
789	  logo:       { type: "asset",  default: null, kind: "image" },
790	  mark:       { type: "string", default: "FRAME JOB" },
791	  tagline:    { type: "string", default: "Edit at the speed of thought" },
792	  background: { type: "color",  default: "#0b0b10" },
793	  accent:     { type: "color",  default: "#ff5a36" },
794	};
795	
796	export function render(frame, props, ctx) {
797	  const u = Math.min(ctx.width, ctx.height) / 1080;
798	  const D = ctx.durationInFrames;
799	  const safeW = ctx.width * 0.9;
800	  const safeH = ctx.height * 0.9;
801	  const cx = ctx.width / 2;
802	  const cy = ctx.height / 2;
803	  let markW;
804	  let markH;
805	  let content;
806	  const markSize = fitText(props.mark, safeW * 0.8, { family: "Montserrat", weight: 900 }, { min: 16 * u, max: 200 * u });
807	  if (props.logo) {
808	    markW = safeW * 0.5;
809	    markH = Math.min(safeH * 0.32, markW);
810	    content = `<image href="${asset(props.logo)}" x="${cx - markW / 2}" y="${cy - markH / 2}" width="${markW}"
811	                      height="${markH}" preserveAspectRatio="xMidYMid meet"/>`;
812	  } else {
813	    markW = measureText(props.mark, { family: "Montserrat", size: markSize, weight: 900 }).width;
814	    markH = markSize * 0.74;
815	    content = `<text x="${cx}" y="${cy + markH / 2}" text-anchor="middle" font-family="Montserrat" font-weight="900"
816	                     font-size="${markSize}" fill="#ffffff">${escapeXml(props.mark)}</text>`;
817	  }
818	  const barH = markH + 80 * u;
819	  const barW = 16 * u;
820	  const from = cx - markW / 2 - 50 * u;
821	  const to = cx + markW / 2 + 50 * u;
822	  const sweep = interpolate(frame, [4, 34], [0, 1], { easing: Easing.inOutCubic, clamp: true });
823	  const barX = from + (to - from) * sweep;
824	  // After its sweep the bar settles into a short rule under the mark.
825	  const morph = interpolate(frame, [36, 54], [0, 1], { easing: Easing.inOutCubic, clamp: true });
826	  const ruleY = cy + markH / 2 + 34 * u;
827	  const bw = barW + (150 * u - barW) * morph;
828	  const bh = barH + (6 * u - barH) * morph;
829	  const bcx = barX + (cx - barX) * morph;
830	  const bcy = cy + (ruleY - cy) * morph;
831	  const settle = interpolate(frame, [4, 54], [1.06, 1], { easing: Easing.outCubic, clamp: true });
832	  const out = interpolate(frame, [D - 15, D - 1], [0, 1], { easing: Easing.inCubic, clamp: true });
833	  const scale = settle + 0.04 * out;
834	  const alpha = 1 - out;
835	  const tagIn = interpolate(frame, [46, 68], [0, 1], { easing: Easing.outCubic, clamp: true });
