841	    <defs>
842	      <clipPath id="wipe"><rect x="${from - 10 * u}" y="${cy - barH / 2}" width="${revealW}" height="${barH}"/></clipPath>
843	    </defs>
844	    <g opacity="${alpha}" transform="translate(${cx} ${cy}) scale(${scale}) translate(${-cx} ${-cy})">
845	      ${sweep >= 1 ? content : revealW > 0.5 ? `<g clip-path="url(#wipe)">${content}</g>` : ""}
846	      ${props.tagline ? `<text x="${cx}" y="${tagY}" text-anchor="middle" font-family="Montserrat" font-weight="800"
847	            font-size="${tagSize}" fill="#d8d8e0" fill-opacity="${tagIn}">${escapeXml(props.tagline)}</text>` : ""}
848	      ${sweep > 0 ? `<rect x="${bcx - bw / 2}" y="${bcy - bh / 2}" width="${bw}" height="${bh}" fill="${props.accent}"/>` : ""}
849	    </g>`, { background: props.background });
850	}
851	// lower-third — road map 10 §5k 1: a slide-in bar and title on a spring, a
852	// staggered subtitle, and an outro keyed to durationInFrames.
853	export const meta = {
854	  name: "Lower third",
855	  category: "Titles & Text",
856	  description: "A name and a subtitle sliding in on a bar.",
857	  durationInFrames: 150,
858	};
859	
860	export const schema = {
861	  title:    { type: "string",  default: "Jane Doe", label: "Title" },
862	  subtitle: { type: "string",  default: "Director of Photography" },
863	  accent:   { type: "color",   default: "#ff5a36" },
864	  size:     { type: "number",  default: 64, min: 12, max: 200, step: 1 },
865	  boxed:    { type: "boolean", default: true },
866	  align:    { type: "enum",    default: "left", options: ["left", "center", "right"] },
867	};
868	
869	export function render(frame, props, ctx) {
870	  const u = Math.min(ctx.width, ctx.height) / 1080;
871	  const size = props.size * u;
872	  const sub = size * 0.5;
873	  const titleFont = { family: "Montserrat", size, weight: 800 };
874	  const subFont = { family: "Montserrat", size: sub, weight: 800 };
875	  const titleWidth = measureText(props.title, titleFont).width;
876	  const subWidth = measureText(props.subtitle, subFont).width;
877	  const boxWidth = Math.max(titleWidth, subWidth) + 80 * u;
878	  const boxHeight = size + sub + 70 * u;
879	  const margin = 96 * u;
880	  const left = props.align === "left" ? margin
881	    : props.align === "right" ? ctx.width - margin - boxWidth
882	    : (ctx.width - boxWidth) / 2;
883	  const top = ctx.height - margin - boxHeight;
884	  const slide = interpolate(frame, [0, 20], [-boxWidth - margin, 0], { easing: Easing.outCubic, clamp: true });
885	  const grow = spring({ frame: frame - 4, fps: ctx.fps, damping: 14 });
886	  const subIn = spring({ frame: frame - 12, fps: ctx.fps, damping: 16 });
887	  const out = interpolate(frame, [ctx.durationInFrames - 15, ctx.durationInFrames - 1], [1, 0], { clamp: true });
888	  const x = left + slide;
889	  const box = props.boxed
890	    ? `<rect x="${x}" y="${top}" width="${boxWidth * grow}" height="${boxHeight}" fill="#101014" fill-opacity="0.82"/>`
891	    : "";
892	  return svg(ctx, `
893	    <g opacity="${out}">
894	      ${box}
895	      <rect x="${x}" y="${top}" width="${12 * u}" height="${boxHeight}" fill="${props.accent}"/>
896	      <text x="${x + 40 * u}" y="${top + 26 * u + size * 0.9}" font-family="Montserrat" font-weight="800"
897	            font-size="${size}" fill="#ffffff">${escapeXml(props.title)}</text>
898	      <text x="${x + 40 * u + (1 - subIn) * 40 * u}" y="${top + 40 * u + size + sub * 0.9}"
899	            font-family="Montserrat" font-weight="800" font-size="${sub}" fill="#d8d8e0"
900	            opacity="${Math.max(0, Math.min(1, subIn))}">${escapeXml(props.subtitle)}</text>
901	    </g>`);
