19	export function render(frame, props, ctx) {
20	  const u = Math.min(ctx.width, ctx.height) / 1080;
21	  const D = ctx.durationInFrames;
22	  const x0 = ctx.width * 0.05;
23	  const bandW = ctx.width * 0.9;
24	  const bandH = 84 * u;
25	  const y = ctx.height * 0.95 - bandH;
26	  const headFont = { family: "Montserrat", size: 38 * u, weight: 900 };
27	  const itemFont = { family: "Montserrat", size: 36 * u, weight: 800 };
28	  const headSize = props.headline ? Math.min(headFont.size, fitText(props.headline, bandW * 0.4,
29	    { family: "Montserrat", weight: 900, letterSpacing: 2 * u }, { min: 10 * u, max: headFont.size })) : 0;
30	  const headW = props.headline
31	    ? measureText(props.headline, { family: "Montserrat", size: headSize, weight: 900, letterSpacing: 2 * u }).width + 56 * u
32	    : 0;
33	  const wipeIn = interpolate(frame, [0, 16], [0, 1], { easing: Easing.outCubic, clamp: true });
34	  const wipeOut = interpolate(frame, [D - 15, D - 1], [0, 1], { easing: Easing.inCubic, clamp: true });
35	  const clipLeft = x0 + bandW * wipeOut;
36	  const clipRight = x0 + bandW * wipeIn;
37	  const pop = spring({ frame: frame - 8, fps: ctx.fps, stiffness: 200, damping: 13 });
38	  const items = props.items.split("|").map((s) => s.trim()).filter((s) => s.length > 0);
39	  const bulletGap = 34 * u;
40	  const bulletR = 7 * u;
41	  const widths = items.map((s) => measureText(s, itemFont).width);
42	  const cycle = widths.reduce((a, w) => a + w + 2 * bulletGap, 0);
43	  const crawlLeft = x0 + headW;
44	  const crawlRight = x0 + bandW;
45	  const baseline = y + bandH / 2 + itemFont.size * 0.36;
46	  let crawl = "";
47	  if (items.length > 0 && cycle > 0) {
48	    const offset = props.speed * u * Math.max(0, ctx.time);
49	    let start = crawlRight - offset;
50	    if (start < crawlLeft - cycle) start += Math.floor((crawlLeft - start) / cycle - 1) * cycle;
51	    for (let k = 0; start + k * cycle < crawlRight; k++) {
52	      let x = start + k * cycle;
53	      items.forEach((s, i) => {
54	        if (x < crawlRight && x + widths[i] > crawlLeft) {
55	          crawl += `<text x="${x}" y="${baseline}" font-family="Montserrat" font-weight="800" font-size="${itemFont.size}"
56	                          fill="#ffffff">${escapeXml(s)}</text>`;
57	        }
58	        x += widths[i] + bulletGap;
59	        crawl += `<circle cx="${x}" cy="${y + bandH / 2}" r="${bulletR}" fill="${props.accent}"/>`;
60	        x += bulletGap;
61	      });
62	    }
63	  }
64	  const hx = x0 + headW / 2;
65	  const hy = y + bandH / 2;
