69	        <text x="${hx}" y="${hy + headSize * 0.36}" text-anchor="middle" font-family="Montserrat" font-weight="900"
70	              font-size="${headSize}" letter-spacing="${2 * u}" fill="#ffffff">${escapeXml(props.headline)}</text>
71	      </g>`
72	    : "";
