74	    <defs>
75	      <clipPath id="band"><rect x="${clipLeft}" y="${y}" width="${Math.max(0, clipRight - clipLeft)}" height="${bandH}"/></clipPath>
76	      <clipPath id="crawl"><rect x="${crawlLeft}" y="${y}" width="${Math.max(0, crawlRight - crawlLeft)}" height="${bandH}"/></clipPath>
77	    </defs>
78	    ${clipRight - clipLeft > 0.5 ? `<g clip-path="url(#band)">
79	      <rect x="${x0}" y="${y}" width="${bandW}" height="${bandH}" fill="${props.background}" fill-opacity="0.92"/>
80	      <rect x="${x0}" y="${y}" width="${bandW}" height="${4 * u}" fill="${props.accent}"/>
