107	  const safeY = ctx.height * 0.05;
108	  const safeW = ctx.width * 0.9;
109	  const safeH = ctx.height * 0.9;
110	  const value = Math.max(0, Math.min(100, props.value));
111	  const trackW = safeW * 0.8;
112	  const trackH = 22 * u;
113	  const padX = 40 * u;
114	  const font = { family: "Montserrat", size: 40 * u, weight: 800 };
115	  const plateW = trackW + 2 * padX;
116	  const plateH = 150 * u;
117	  const plateX = (ctx.width - plateW) / 2;
118	  const margin = 40 * u;
119	  const plateY = props.position === "top" ? safeY + margin
120	    : props.position === "center" ? (ctx.height - plateH) / 2
121	    : safeY + safeH - margin - plateH;
122	  const trackX = plateX + padX;
123	  const trackY = plateY + plateH - 40 * u - trackH;
124	  const textY = plateY + 40 * u + font.size * 0.72;
125	  const fillEnd = Math.max(16, Math.round(D * 0.6));
126	  const grown = interpolate(frame, [8, fillEnd], [0, 1], { easing: Easing.outCubic, clamp: true });
127	  const fillW = (trackW * value * grown) / 100;
128	  const plateIn = interpolate(frame, [0, 10], [0, 1], { clamp: true });
129	  const wipe = interpolate(frame, [2, 20], [0, 1], { easing: Easing.outCubic, clamp: true });
130	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
131	  const shine = interpolate(frame, [fillEnd - 6, fillEnd + 24], [-0.3, 1.3], { easing: Easing.inOutSine, clamp: true });
132	  const shineX = trackX + fillW * shine;
133	  const percent = `${Math.round(value * grown)}%`;
134	  const labelMax = trackW - (props.showPercent ? 200 * u : 0);
135	  const labelSize = Math.min(font.size, fitText(props.label, labelMax, font, { min: 10 * u, max: font.size }));
136	  return svg(ctx, `
137	    <defs>
138	      <clipPath id="wipe"><rect x="${plateX}" y="${plateY}" width="${plateW * wipe}" height="${plateH}"/></clipPath>
139	      <clipPath id="fill"><rect x="${trackX}" y="${trackY}" width="${fillW}" height="${trackH}" rx="${trackH / 2}"/></clipPath>
140	      <linearGradient id="shine" x1="0" y1="0" x2="1" y2="0">
141	        <stop offset="0" stop-color="#ffffff" stop-opacity="0"/>
142	        <stop offset="0.5" stop-color="#ffffff" stop-opacity="0.55"/>
143	        <stop offset="1" stop-color="#ffffff" stop-opacity="0"/>
144	      </linearGradient>
145	    </defs>
146	    <g opacity="${out * plateIn}">
147	      <rect x="${plateX}" y="${plateY}" width="${plateW}" height="${plateH}" rx="${18 * u}" fill="#101014"
148	            fill-opacity="0.82"/>
149	      <g clip-path="url(#wipe)">
150	        <text x="${trackX}" y="${textY}" font-family="Montserrat" font-weight="800" font-size="${labelSize}"
151	              fill="#ffffff">${escapeXml(props.label)}</text>
152	        ${props.showPercent ? `<text x="${trackX + trackW}" y="${textY}" text-anchor="end" font-family="IBM Plex Mono"
153	              font-weight="500" font-size="${font.size}" fill="#d8d8e0">${percent}</text>` : ""}
154	        <rect x="${trackX}" y="${trackY}" width="${trackW}" height="${trackH}" rx="${trackH / 2}" fill="#ffffff"
155	              fill-opacity="0.12"/>
156	        ${fillW > 0.5 ? `<rect x="${trackX}" y="${trackY}" width="${fillW}" height="${trackH}" rx="${trackH / 2}"
157	              fill="${props.accent}"/>
158	        <g clip-path="url(#fill)"><rect x="${shineX - 90 * u}" y="${trackY}" width="${180 * u}" height="${trackH}"
159	              fill="url(#shine)"/></g>` : ""}
160	      </g>
161	    </g>`);
162	}
