240	    ${attrIn > 0 ? `<rect x="${left + slide}" y="${attrY - attrSize - 34 * u}" width="${80 * u}" height="${6 * u}"
241	          fill="${props.accent}" fill-opacity="${attrIn * out}"/>
242	    <text x="${left + slide}" y="${attrY}" font-family="Montserrat" font-weight="800"
